 "content": "def transform(grid):
    """Overlay four 3-row layers; color priority is 5, then 4, then 2."""
    if len(grid) != 12:
        raise ValueError("Expected four 3-row layers")
    return [
        [next((color for color in (5, 4, 2)
               if any(grid[k * 3 + r][c] == color for k in range(4))), 0)
         for c in range(len(grid[0]))]
        for r in range(3)
    ]

if __name__ == "__main__":
    demo = [
        [0,5,5,5,5,0],[5,5,0,5,5,5],[5,5,0,5,0,0],
        [0,0,4,0,0,0],[4,0,4,4,4,0],[4,0,0,0,0,0],
